"use strict";const t=require("../utils/request.js");exports.aiInsights=function(e){return t.http.get(`/reports/ai-insights?month=${e}`)},exports.categoryReport=function(e,r,n="expense"){return t.http.get(`/reports/category?from=${e}&to=${r}&kind=${n}`)},exports.dimensionReport=function(e,r,n,o="expense"){return t.http.get(`/reports/dimension?from=${e}&to=${r}&dim=${n}&kind=${o}`)},exports.memberReport=function(e,r,n="expense"){return t.http.get(`/reports/members?from=${e}&to=${r}&kind=${n}`)},exports.monthRange=function(t){const[e,r]=t.split("-").map(Number),n=new Date(e,r,0).getDate(),o=String(r).padStart(2,"0");return{from:`${e}-${o}-01`,to:`${e}-${o}-${String(n).padStart(2,"0")}`}},exports.monthlyDigest=function(e){return t.http.get(`/reports/monthly-digest?month=${e}`)},exports.personalityTags=function(e){return t.http.get(`/reports/personality-tags?month=${e}`)},exports.shiftMonth=function(t,e){const[r,n]=t.split("-").map(Number),o=new Date(r,n-1+e,1);return`${o.getFullYear()}-${String(o.getMonth()+1).padStart(2,"0")}`},exports.trendReport=function(e,r){return t.http.get(`/reports/trend?fromMonth=${e}&toMonth=${r}`)};
